#!/usr/bin/env node
/**
 * Generate help-manifest.json from manifest.json + help-topics-meta.json (P72 follow-up).
 *
 * SSOT split:
 *   manifest.json         — static site nav + all published topics
 *   help-topics-meta.json — CMS Help ids, keywords, ai_topic (keyed by .md path)
 *   help-manifest.json    — GENERATED — do not edit by hand
 *
 * Usage: node scripts/generate-help-manifest.js [--check]
 *   --check  Exit 1 if help-manifest.json would change (CI gate)
 */

const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const checkOnly = process.argv.includes('--check');

const manifest = JSON.parse(fs.readFileSync(path.join(root, 'manifest.json'), 'utf8'));
const metaFile = JSON.parse(fs.readFileSync(path.join(root, 'help-topics-meta.json'), 'utf8'));
const metaTopics = metaFile.topics || {};

/** @type {Set<string>} */
const manifestPaths = new Set();
for (const section of manifest.sections) {
  for (const item of section.items) {
    manifestPaths.add(item.path.replace(/\\/g, '/'));
  }
}

const topics = [];
const errors = [];

for (const [mdPath, meta] of Object.entries(metaTopics)) {
  if (!manifestPaths.has(mdPath)) {
    errors.push(`help-topics-meta: ${mdPath} not in manifest.json`);
    continue;
  }
  if (!meta.id) {
    errors.push(`help-topics-meta: ${mdPath} missing id`);
    continue;
  }
  const entry = {
    id: meta.id,
    title: meta.title || meta.id,
    keywords: meta.keywords || [],
    docs_path: mdPath.replace(/\.md$/, '.html'),
  };
  if (meta.ai_topic) entry.ai_topic = meta.ai_topic;
  if (meta.nav_section) entry.nav_section = meta.nav_section;
  if (meta.nav_section_label) entry.nav_section_label = meta.nav_section_label;
  if (meta.version) entry.version = meta.version;
  if (meta.section) entry.section = meta.section;
  topics.push(entry);
}

topics.sort((a, b) => a.id.localeCompare(b.id));

if (errors.length) {
  console.error(errors.join('\n'));
  process.exit(1);
}

const out = {
  version: metaFile.version ?? 3,
  docs_base_url: metaFile.docs_base_url ?? 'https://docs.birkly.com',
  manifest_version: metaFile.manifest_version ?? 'generated',
  description: metaFile.description ?? 'Public help manifest for Birkly CMS live fetch. GENERATED by scripts/generate-help-manifest.js',
  topics,
};

const outPath = path.join(root, 'help-manifest.json');
const json = JSON.stringify(out, null, 4) + '\n';

if (checkOnly) {
  const current = fs.existsSync(outPath) ? fs.readFileSync(outPath, 'utf8') : '';
  if (current !== json) {
    console.error('help-manifest.json is out of date — run: npm run generate:help');
    process.exit(1);
  }
  console.log(`help-manifest.json OK (${topics.length} topics)`);
  process.exit(0);
}

fs.writeFileSync(outPath, json);
console.log(`Wrote help-manifest.json (${topics.length} topics)`);
